import { db } from '../firebase';
import { ref, push, onValue, set, update } from 'firebase/database';

// Пользователи
export const saveUser = async (user) => {
  if (!user?.id) return;
  await set(ref(db, `users/${user.id}`), user);
};

export const updateUser = async (userId, data) => {
  if (!userId) return;
  await update(ref(db, `users/${userId}`), data);
};

export const listenUsers = (cb) => {
  const r = ref(db, 'users');
  return onValue(r, (snap) => {
    const data = snap.val();
    cb(data ? Object.values(data) : []);
  });
};

// Сообщения
export const listenMessages = (cb) => {
  const r = ref(db, 'messages');
  return onValue(r, (snap) => {
    const data = snap.val();
    const arr = data ? Object.values(data) : [];
    cb(arr.reverse());
  });
};

export const sendMessage = async (msg) => {
  await push(ref(db, 'messages'), msg);
};

// Присутствие
export const updateLastSeen = async (userId) => {
  if (!userId) return;
  await update(ref(db, `users/${userId}`), { lastSeen: Date.now() });
};
