import { useEffect, useState } from 'react';
import bridge from '@vkontakte/vk-bridge';
import { saveUser } from '../services/firebaseService';

const GUEST = {
  id: 'test123',
  name: 'Тест Пользователь',
  avatar: 'https://vk.com/images/camera_200.png',
  about: '',
};

export default function useVKUser() {
  const [user, setUser] = useState(null);

  useEffect(() => {
    let done = false;

    const setAndSave = (u) => {
      setUser(u);
      // lastSeen запишем тут же
      saveUser({ ...u, lastSeen: Date.now() }).catch(() => {});
    };

    bridge
      .send('VKWebAppGetUserInfo')
      .then((data) => {
        done = true;
        const u = {
          id: data.id,
          name: `${data.first_name} ${data.last_name}`,
          avatar: data.photo_200,
          about: '',
        };
        setAndSave(u);
      })
      .catch(() => {
        done = true;
        setAndSave(GUEST);
      });

    // Фолбэк на случай подвисания Bridge на мобилках
    const t = setTimeout(() => {
      if (!done) setAndSave(GUEST);
    }, 3000);

    return () => clearTimeout(t);
  }, []);

  return user;
}
