import React, { useState, useRef, useEffect } from 'react';
import { Button, useAdaptivity } from '@vkontakte/vkui';
import { Icon28SmileOutline } from '@vkontakte/icons';

import { Picker } from 'emoji-mart';

export default function BottomBar({ onSend, text, setText }) {
  const { sizeX } = useAdaptivity();
  const isMobile = sizeX === 'compact';
  const btnSize = isMobile ? 24 : 28;
  const pickerRef = useRef(null);
  const textareaRef = useRef(null);

  const [showEmoji, setShowEmoji] = useState(false);

  const addEmoji = (emoji) => {
    setText(prev => prev + emoji.native);
    setShowEmoji(false);
  };

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (pickerRef.current && !pickerRef.current.contains(event.target)) {
        setShowEmoji(false);
      }
    };
    if (showEmoji) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showEmoji]);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`;
    }
  }, [text]);

  const pickerHeight = typeof window !== 'undefined'
    ? Math.min(300, window.innerHeight * 0.4)
    : 300;

  return (
    <div style={{
      display: 'flex',
      alignItems: 'flex-end',
      gap: isMobile ? 4 : 8,
      padding: isMobile ? '4px 6px' : '6px 8px',
      borderTop: '1px solid var(--vkui--color_separator_primary)',
      background: 'var(--vkui--color_background_content)',
      position: 'relative'
    }}>
      <Button mode="tertiary" size="l" onClick={() => setShowEmoji(p => !p)}>
        <Icon28SmileOutline width={btnSize} height={btnSize} />
      </Button>

      {showEmoji && (
        <div
          ref={pickerRef}
          style={{
            position: 'absolute',
            bottom: isMobile ? '50px' : '60px',
            left: 0,
            zIndex: 1000,
            animation: 'slideUp 0.25s ease-out',
            maxHeight: pickerHeight,
            overflowY: 'auto',
            background: 'var(--vkui--color_background_content)',
            borderRadius: 8
          }}
        >
          <Picker onSelect={addEmoji} />
        </div>
      )}

      <textarea
        ref={textareaRef}
        value={text}
        onChange={(e) => setText(e.target.value)}
        style={{
          flex: 1,
          resize: 'none',
          padding: isMobile ? '6px' : '8px',
          borderRadius: '8px',
          border: '1px solid #ddd',
          maxHeight: '150px',
          overflowY: 'auto',
          fontSize: isMobile ? '13px' : '14px'
        }}
        placeholder="Введите сообщение"
        onKeyDown={(e) => {
          if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            onSend();
          }
        }}
      />

      <Button
        mode="primary"
        size={isMobile ? 'm' : 'l'}
        onClick={onSend}
        disabled={!text.trim()}
      >
        Отправить
      </Button>

      <style>
        {`
          @keyframes slideUp {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
          }
        `}
      </style>
    </div>
  );
}