import React from 'react';
import { Group, ModalPage, ModalPageHeader } from '@vkontakte/vkui';

export default function OnlineUsersModal({ id, onlineUsers, onClose }) {
  return (
    <ModalPage id={id} onClose={onClose} header={<ModalPageHeader>Онлайн пользователи</ModalPageHeader>}>
      <Group>
        {onlineUsers.length === 0 && <div>Никто не онлайн 😢</div>}
        {onlineUsers.map((u, i) => (
          <div key={i} style={{
            display: 'flex',
            alignItems: 'center',
            marginBottom: 6,
            background: '#e7e8ec',
            padding: 6,
            borderRadius: 6
          }}>
            <img src={u.avatar} alt="avatar" width={24} height={24} />
            <div style={{ marginLeft: 8 }}>{u.name}</div>
          </div>
        ))}
      </Group>
    </ModalPage>
  );
}
