import React from 'react';
import { Group, FormItem, Textarea, Button, ModalPage, ModalPageHeader } from '@vkontakte/vkui';

export default function UserModal({ id, user, aboutText, setAboutText, onSave, onClose }) {
  return (
    <ModalPage id={id} onClose={onClose} header={<ModalPageHeader>Ваш профиль</ModalPageHeader>}>
      <Group>
        <div style={{ display: 'flex', alignItems: 'center', marginBottom: 12 }}>
          <img src={user.avatar} alt="avatar" width={48} height={48} style={{ borderRadius: 24 }} />
          <div style={{ marginLeft: 12 }}>
            <strong>{user.name}</strong>
            <div style={{ fontSize: 12, color: 'gray' }}>ID: {user.id}</div>
          </div>
        </div>
        <FormItem top="О себе">
          <Textarea value={aboutText} onChange={e => setAboutText(e.target.value)} placeholder="Напишите немного о себе" />
          <Button onClick={onSave} style={{ marginTop: 8 }}>Сохранить</Button>
        </FormItem>
      </Group>
    </ModalPage>
  );
}
