import React, { useState } from 'react';
import {
  PanelHeader,
  PanelHeaderButton,
  ActionSheet,
  ActionSheetItem,
  useAdaptivity
} from '@vkontakte/vkui';
import {
  Icon28UserOutline,
  Icon28SettingsOutline,
  Icon28MoreHorizontal
} from '@vkontakte/icons';

export default function HeaderBar({ onOpenProfile, onOpenSettings, onToggleTheme }) {
  const { sizeX } = useAdaptivity();
  const isMobile = sizeX === 'compact';
  const btnSize = isMobile ? 24 : 28;

  const [showMenu, setShowMenu] = useState(false);

  return (
    <>
      <PanelHeader
        before={
          <PanelHeaderButton aria-label="Профиль" onClick={onOpenProfile}>
            <Icon28UserOutline width={btnSize} height={btnSize} />
          </PanelHeaderButton>
        }
        after={
          <>
            <PanelHeaderButton aria-label="Настройки" onClick={onOpenSettings}>
              <Icon28SettingsOutline width={btnSize} height={btnSize} />
            </PanelHeaderButton>
            <PanelHeaderButton aria-label="Меню" onClick={() => setShowMenu(true)}>
              <Icon28MoreHorizontal width={btnSize} height={btnSize} />
            </PanelHeaderButton>
          </>
        }
      >
        VK Чат
      </PanelHeader>

      {showMenu && (
        <ActionSheet onClose={() => setShowMenu(false)}>
          <ActionSheetItem autoclose onClick={() => alert('Поиск по чату')}>🔍 Поиск по чату</ActionSheetItem>
          <ActionSheetItem autoclose onClick={() => alert('Очистить чат')}>🗑 Очистить чат</ActionSheetItem>
          <ActionSheetItem autoclose onClick={onToggleTheme}>🎨 Сменить тему</ActionSheetItem>
          <ActionSheetItem autoclose mode="cancel">Отмена</ActionSheetItem>
        </ActionSheet>
      )}
    </>
  );
}