import React, { useEffect, useRef, useState } from 'react';
import {
  ConfigProvider,
  AdaptivityProvider,
  AppRoot,
  View,
  Panel,
  Group,
  ModalRoot
} from '@vkontakte/vkui';
import '@vkontakte/vkui/dist/vkui.css';

import useVKUser from './hooks/useVKUser';
import useChat from './hooks/useChat';

import HeaderBar from './components/HeaderBar';
import BottomBar from './components/BottomBar';
import MessageList from './components/MessageList';
import UserModal from './components/UserModal';
import OnlineUsersModal from './components/OnlineUsersModal';

function App() {
  const user = useVKUser();
  const { visibleMessages, onlineUsers, sendMessage, saveAbout } = useChat(user);

  const [text, setText] = useState('');
  const [activeModal, setActiveModal] = useState(null);
  const [aboutText, setAboutText] = useState('');
  const [scheme, setScheme] = useState(() => localStorage.getItem('theme') || 'bright_light');
  const chatEndRef = useRef(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [visibleMessages]);

  const handleSend = async () => {
    if (!text.trim()) return;
    await sendMessage(text);
    setText('');
  };

  const openProfile = () => {
    setAboutText(user?.about || '');
    setActiveModal('profile');
  };

  const handleSaveAbout = async () => {
    await saveAbout(aboutText);
    setActiveModal(null);
  };

  const toggleTheme = () => {
    const next = scheme === 'bright_light' ? 'space_gray' : 'bright_light';
    setScheme(next);
    localStorage.setItem('theme', next);
  };

  const modal = (
    <ModalRoot activeModal={activeModal}>
      {user && (
        <UserModal
          id="profile"
          user={user}
          aboutText={aboutText}
          setAboutText={setAboutText}
          onSave={handleSaveAbout}
          onClose={() => setActiveModal(null)}
        />
      )}
      <OnlineUsersModal
        id="online"
        onlineUsers={onlineUsers}
        onClose={() => setActiveModal(null)}
      />
    </ModalRoot>
  );

  return (
    <ConfigProvider scheme={scheme}>
      <AdaptivityProvider>
        <AppRoot>
          <View activePanel="main" modal={modal}>
            <Panel id="main">
              <HeaderBar
                onOpenProfile={openProfile}
                onOpenSettings={() => setActiveModal('online')}
                onToggleTheme={toggleTheme}
              />

              <Group style={{ height: 'calc(100vh - 112px)', overflowY: 'auto', padding: 16 }}>
                <MessageList messages={visibleMessages} currentUserId={user?.id} />
                <div ref={chatEndRef} />
              </Group>

              <BottomBar text={text} setText={setText} onSend={handleSend} />
            </Panel>
          </View>
        </AppRoot>
      </AdaptivityProvider>
    </ConfigProvider>
  );
}

export default App;