import React from 'react';

export default function MessageList({ messages, currentUserId, endRef }) {
  return (
    <div style={{
      display: 'flex',
      flexDirection: 'column-reverse',
      maxHeight: '60vh',
      overflowY: 'auto',
      paddingBottom: 10
    }}>
      <div ref={endRef} />
      {messages.map((msg, i) => {
        const isPrivate = msg.type === 'private';
        const isMention = msg.type === 'mention';
        const isToMe = msg.targetId === currentUserId;
        const isFromMe = msg.from === currentUserId;

        const bgColor = isPrivate ? '#f3e8ff' :
                        isMention ? '#fff8dc' : '#f2f3f5';
        const textColor = isPrivate && (isToMe || isFromMe) ? '#6a0dad' : 'black';

        return (
          <div key={i} style={{
            display: 'flex',
            alignItems: 'center',
            marginBottom: 10,
            background: bgColor,
            padding: 10,
            borderRadius: 8
          }}>
            <img src={msg.avatar} alt="avatar" width={32} height={32} />
            <div style={{ marginLeft: 10 }}>
              <strong>{msg.name}</strong>
              <div style={{ color: textColor }}>{msg.text}</div>
              {isPrivate && <div style={{ fontSize: 12, color: '#6a0dad' }}>Личное сообщение</div>}
              {isMention && isToMe && <div style={{ fontSize: 12, color: 'orange' }}>Упоминание вас</div>}
            </div>
          </div>
        );
      })}
    </div>
  );
}
